<?php
declare(strict_types=1);
require_once __DIR__ . '/../src/seed.php';
require_once __DIR__ . '/../src/domain.php';
require_once __DIR__ . '/../src/store.php';
$passed=0;
function test(string $name, callable $fn): void { global $passed; try{$fn();echo "PASS $name\n";$passed++;}catch(Throwable $e){fwrite(STDERR,"FAIL $name: {$e->getMessage()}\n");exit(1);} }
function check(bool $value, string $message='Assertion failed'): void {if(!$value)throw new RuntimeException($message);}
function rejects(callable $fn, string $contains=''): void {try{$fn();}catch(DomainError $e){check(!$contains||str_contains($e->getMessage(),$contains),$e->getMessage());return;}throw new RuntimeException('Expected domain rejection');}
function event_cmd(array $ids): array {return ['type'=>'create_event','name'=>'Prueba parcial','place'=>'Escenario A','responsible'=>'Krew QA','vehicle'=>'Camión QA','start'=>date('Y-m-d',strtotime('+1 day')).'T10:00','end'=>date('Y-m-d',strtotime('+2 days')).'T10:00','assetIds'=>$ids];}
function asset(array $s,string $id): array {return $s['assets'][entity_index($s['assets'],$id)];}
test('Inventario demo consistente, identificadores únicos, piezas sin doble conteo',function(){ $s=seed_state();check(count($s['assets'])===151);check(count(array_unique(array_column($s['assets'],'id')))===151);foreach($s['kits'] as $k){check(count($k['expectedIds'])===33);foreach($k['expectedIds'] as $id)check(asset($s,$id)['kitId']===$k['id']);} });
test('Salida parcial conserva identidad y no mueve las piezas restantes',function(){ $s=seed_state();$s=apply_command($s,event_cmd(['TAM-SCM-001-BD1','TAM-SCM-001-T10']),'QA');check(asset($s,'TAM-SCM-001-BD1')['status']==='reserved');check(asset($s,'TAM-SCM-001-T12')['status']==='available');check(!$s['kits'][0]['assembled']);check($s['revision']===1); });
test('Un kit completo puede reservarse como sus 33 activos reales',function(){ $s=seed_state();$s=apply_command($s,event_cmd($s['kits'][0]['expectedIds']),'QA');check(count(array_filter($s['assets'],fn($a)=>$a['status']==='reserved'))===33);check(count(end($s['events'])['items'])===33); });
test('Evita reservar dos veces una pieza entre eventos',function(){ $s=apply_command(seed_state(),event_cmd(['TAM-SCM-001-BD1']),'QA');rejects(fn()=>apply_command($s,event_cmd(['TAM-SCM-001-BD1']),'Otro encargado'),'ya está'); });
test('Rechaza equipos duplicados en una orden',function(){rejects(fn()=>apply_command(seed_state(),event_cmd(['MAR-1960B-001','MAR-1960B-001']),'QA'),'repetidos');});
test('Rechaza equipo fuera de servicio y valida toda la selección antes de mutar',function(){ $s=seed_state();rejects(fn()=>apply_command($s,event_cmd(['MAR-1960B-001','HW-BOOM-008']),'QA'),'revisión');check(asset($s,'MAR-1960B-001')['status']==='available'); });
test('No admite devolución sin salida física',function(){ $s=apply_command(seed_state(),event_cmd(['MAR-1960B-001']),'QA');$e=end($s['events']);rejects(fn()=>apply_command($s,['type'=>'return','responsibleId'=>'TEC-02','eventId'=>$e['id'],'assetIds'=>['MAR-1960B-001']],'QA'),'aún no ha salido'); });
test('Salida y retorno parcial actualizan evento, ubicación y auditoría',function(){ $s=apply_command(seed_state(),event_cmd(['TAM-SCM-001-BD1','TAM-SCM-001-T10']),'Krew QA');$id=end($s['events'])['id'];$s=apply_command($s,['type'=>'dispatch','responsibleId'=>'TEC-01','eventId'=>$id,'assetIds'=>['TAM-SCM-001-BD1']],'Encargado');check(asset($s,'TAM-SCM-001-BD1')['location']==='Escenario A');check(asset($s,'TAM-SCM-001-T10')['status']==='reserved');$s=apply_command($s,['type'=>'return','responsibleId'=>'TEC-02','eventId'=>$id,'assetIds'=>['TAM-SCM-001-BD1'],'condition'=>'ok'],'Bodega');check(asset($s,'TAM-SCM-001-BD1')['status']==='available');check(asset($s,'TAM-SCM-001-BD1')['eventId']===null);check($s['movements'][0]['actor']==='Bodega'); });
test('Un daño bloquea disponibilidad hasta revisión técnica',function(){ $s=seed_state();$s=apply_command($s,['type'=>'return','responsibleId'=>'TEC-02','eventId'=>'EVT-DEMO-002','assetIds'=>['MAR-1960B-003'],'condition'=>'damage','note'=>'Rueda suelta'],'QA');check(asset($s,'MAR-1960B-003')['status']==='maintenance');rejects(fn()=>apply_command($s,event_cmd(['MAR-1960B-003']),'QA'));$s=apply_command($s,['type'=>'maintenance','assetIds'=>['MAR-1960B-003'],'ready'=>true,'note'=>'Rueda reparada'],'Técnico');check(asset($s,'MAR-1960B-003')['status']==='available'); });
test('Un faltante no se convierte en stock disponible y puede recuperarse',function(){ $cmd=['type'=>'return','responsibleId'=>'TEC-02','eventId'=>'EVT-DEMO-002','assetIds'=>['MAR-1960B-003'],'condition'=>'missing','note'=>'Quedó en recinto'];$s=apply_command(seed_state(),$cmd,'QA');check(asset($s,'MAR-1960B-003')['status']==='missing');check(asset($s,'MAR-1960B-003')['eventId']==='EVT-DEMO-002');$cmd['condition']='ok';$s=apply_command($s,$cmd,'QA');check(asset($s,'MAR-1960B-003')['status']==='available'); });
test('Daños y faltantes requieren descripción',function(){rejects(fn()=>apply_command(seed_state(),['type'=>'return','responsibleId'=>'TEC-02','eventId'=>'EVT-DEMO-002','assetIds'=>['MAR-1960B-003'],'condition'=>'damage'],'QA'),'Describe');});
test('No permite mover un activo usando otro evento',function(){rejects(fn()=>apply_command(seed_state(),['type'=>'return','responsibleId'=>'TEC-02','eventId'=>'EVT-DEMO-001','assetIds'=>['MAR-1960B-003']],'QA'),'no está asignado');});
test('Reasignación no permite armar un kit incompleto',function(){ $s=apply_command(seed_state(),['type'=>'assign_kit','assetId'=>'TAM-SCM-001-T12','kitId'=>'TAM-SCM-002'],'QA');check(asset($s,'TAM-SCM-001-T12')['kitId']==='TAM-SCM-002');rejects(fn()=>apply_command($s,['type'=>'kit_mode','kitId'=>'TAM-SCM-001','assembled'=>true],'QA'),'Faltan'); });
test('Pieza fuera de bodega no se reasigna a otro kit',function(){rejects(fn()=>apply_command(seed_state(),['type'=>'assign_kit','assetId'=>'MAR-1960B-003','kitId'=>'TAM-SCM-001'],'QA'),'disponibles');});
test('Liberar una reserva habilita la pieza sin simular una devolución',function(){ $s=apply_command(seed_state(),event_cmd(['MAR-1960B-001']),'QA');$id=end($s['events'])['id'];$s=apply_command($s,['type'=>'release','eventId'=>$id,'assetIds'=>['MAR-1960B-001']],'QA');check(asset($s,'MAR-1960B-001')['status']==='available');check(end($s['events'])['items'][0]['status']==='released'); });
test('Fechas invertidas y códigos repetidos se rechazan',function(){ $c=event_cmd(['MAR-1960B-001']);$c['end']='2020-01-01T10:00';rejects(fn()=>apply_command(seed_state(),$c,'QA'),'posterior');rejects(fn()=>apply_command(seed_state(),['type'=>'create_asset','code'=>'MAR-1960B-001','name'=>'Duplicado'],'QA'),'ya existe'); });
test('La pieza conserva su historial al separarse del kit',function(){ $s=apply_command(seed_state(),['type'=>'kit_mode','kitId'=>'TAM-SCM-001','assembled'=>false],'QA');check(count($s['assets'])===151);check(asset($s,'TAM-SCM-001-T12')['kitId']==='TAM-SCM-001');$s=apply_command($s,['type'=>'kit_mode','kitId'=>'TAM-SCM-001','assembled'=>true],'QA');check($s['kits'][0]['assembled']);check(count($s['movements'])===3); });
test('Cada Tama es doble bombo con fierros, sillín e hi-hat completo',function(){ $s=seed_state();foreach($s['kits'] as $n=>$k){$parts=array_map(fn($id)=>asset($s,$id),$k['expectedIds']);$names=array_column($parts,'name');$count=fn($re)=>count(array_filter($names,fn($x)=>preg_match($re,$x)));check($count('/^Bombo 22” · /')===2);check($count('/^Caja 14” · /')===1);check(asset($s,$k['id'].'-SN')['brand']===($n===0?'Mapex':'Tama'));check($count('/^Tom (10|12|13)”$/')===3);check($count('/^Tom de piso (14|16)”$/')===2);check($count('/^Atril con boom /')===4);check($count('/^Atril recto /')===2);check($count('/^Atril de caja$/')===1);check($count('/^Pedal de bombo /')===2);check($count('/^Pedal doble$/')===1);check($count('/^Soporte de tom /')===3);check($count('/^Sillín$/')===1);check($count('/^(Atril hi-hat 3 patas|Varilla hi-hat|Clutch hi-hat)$/')===3);check($count('/^Funda /')===8);} });
test('Tambores y fierros del mismo kit salen a eventos distintos y el kit no se rearma hasta que vuelven',function(){ $s=seed_state();$k=$s['kits'][0];$drums=array_values(array_filter($k['expectedIds'],fn($id)=>asset($s,$id)['category']==='Tambores'));$hardware=array_values(array_diff($k['expectedIds'],$drums));check(count($drums)===8&&count($hardware)===25);$s=apply_command($s,event_cmd($drums),'QA');$a=end($s['events'])['id'];$s=apply_command($s,event_cmd($hardware),'QA');$b=end($s['events'])['id'];check($a!==$b);foreach($drums as $id)check(asset($s,$id)['eventId']===$a);foreach($hardware as $id)check(asset($s,$id)['eventId']===$b);check($s['kits'][0]['assembled']===false);rejects(fn()=>apply_command($s,['type'=>'kit_mode','kitId'=>$k['id'],'assembled'=>true],'QA'),'reservadas');foreach([[$a,$drums],[$b,$hardware]] as [$ev,$ids]){$s=apply_command($s,['type'=>'release','eventId'=>$ev,'assetIds'=>$ids],'QA');}$s=apply_command($s,['type'=>'kit_mode','kitId'=>$k['id'],'assembled'=>true],'QA');check($s['kits'][0]['assembled']===true);foreach($k['expectedIds'] as $id)check(asset($s,$id)['status']==='available'); });
test('Traslado entre bodegas: el kit completo se mueve armado y vuelve a su nueva bodega tras el evento',function(){ $s=seed_state();$k=$s['kits'][1];foreach($s['assets'] as $a)check(($a['home']??'')==='Bodega A');$s=apply_command($s,['type'=>'transfer','assetIds'=>$k['expectedIds'],'warehouse'=>'Bodega B'],'QA');foreach($k['expectedIds'] as $id){check(asset($s,$id)['location']==='Bodega B');check(asset($s,$id)['home']==='Bodega B');}check($s['kits'][1]['assembled']===true);check($s['movements'][0]['type']==='transfer');$s=apply_command($s,event_cmd([$k['id'].'-SN']),'QA');$ev=end($s['events'])['id'];$s=apply_command($s,['type'=>'dispatch','responsibleId'=>'TEC-01','eventId'=>$ev,'assetIds'=>[$k['id'].'-SN']],'QA');$s=apply_command($s,['type'=>'return','responsibleId'=>'TEC-02','eventId'=>$ev,'assetIds'=>[$k['id'].'-SN'],'condition'=>'ok'],'QA');check(asset($s,$k['id'].'-SN')['location']==='Bodega B');$s=apply_command($s,['type'=>'maintenance','assetIds'=>[$k['id'].'-T10'],'ready'=>false],'QA');$s=apply_command($s,['type'=>'maintenance','assetIds'=>[$k['id'].'-T10'],'ready'=>true],'QA');check(asset($s,$k['id'].'-T10')['location']==='Bodega B'); });
test('Traslado rechaza bodegas desconocidas y piezas fuera de bodega',function(){ $s=seed_state();rejects(fn()=>apply_command($s,['type'=>'transfer','assetIds'=>['MAR-1960B-001'],'warehouse'=>'Bodega C'],'QA'),'Bodega');rejects(fn()=>apply_command($s,['type'=>'transfer','assetIds'=>['MAR-1960B-003'],'warehouse'=>'Bodega B'],'QA'),'no está disponible');rejects(fn()=>apply_command($s,['type'=>'create_asset','code'=>'TEST-001','name'=>'X','location'=>'Casa'],'QA'),'Bodega');$s=apply_command($s,['type'=>'create_asset','code'=>'TEST-001','name'=>'X','location'=>'Bodega B'],'QA');check(asset($s,'TEST-001')['home']==='Bodega B'); });
test('Salidas y devoluciones exigen técnico responsable y lo registran',function(){ $s=seed_state();check(count($s['crew'])===10);$s=apply_command($s,event_cmd(['MAR-1960B-001']),'QA');$ev=end($s['events'])['id'];rejects(fn()=>apply_command($s,['type'=>'dispatch','eventId'=>$ev,'assetIds'=>['MAR-1960B-001']],'QA'),'técnico');rejects(fn()=>apply_command($s,['type'=>'dispatch','eventId'=>$ev,'assetIds'=>['MAR-1960B-001'],'responsibleId'=>'TEC-99'],'QA'),'técnico');$s=apply_command($s,['type'=>'crew_rename','crewId'=>'TEC-03','name'=>'Krew Norte A'],'QA');rejects(fn()=>apply_command($s,['type'=>'crew_rename','crewId'=>'TEC-04','name'=>'krew norte a'],'QA'),'Ya hay');$s=apply_command($s,['type'=>'dispatch','eventId'=>$ev,'assetIds'=>['MAR-1960B-001'],'responsibleId'=>'TEC-03'],'QA');check(str_contains($s['movements'][0]['summary'],'Krew Norte A'));check($s['movements'][0]['responsible']==='Krew Norte A');$s=apply_command($s,['type'=>'return','eventId'=>$ev,'assetIds'=>['MAR-1960B-001'],'condition'=>'ok','responsibleId'=>'TEC-07'],'QA');$it=end($s['events'])['items'][0];check($it['outBy']==='Krew Norte A'&&$it['inBy']==='Técnico 07');$legacy=seed_state();unset($legacy['crew']);$legacy=apply_command($legacy,event_cmd(['MAR-1960B-002']),'QA');$e2=end($legacy['events'])['id'];$legacy=apply_command($legacy,['type'=>'dispatch','eventId'=>$e2,'assetIds'=>['MAR-1960B-002'],'responsibleId'=>'TEC-01'],'QA');check(count($legacy['crew'])===10); });
test('Evento guarda conductor y teléfonos, y rechaza teléfonos inválidos',function(){ $c=event_cmd(['MAR-1960B-001']);$c+= ['driver'=>'Conductor QA','responsiblePhone'=>'+56 9 1234 5678','driverPhone'=>'(2) 2345-6789'];$s=apply_command(seed_state(),$c,'QA');$e=end($s['events']);check($e['driver']==='Conductor QA'&&$e['responsiblePhone']==='+56 9 1234 5678'&&$e['driverPhone']==='(2) 2345-6789');$c['driverPhone']='llamar <script>';rejects(fn()=>apply_command(seed_state(),$c,'QA'),'teléfono'); });
test('Informe de daño o faltante: técnico obligatorio, cambia estado en bodega y se puede cerrar',function(){ $s=seed_state();rejects(fn()=>apply_command($s,['type'=>'report_issue','assetIds'=>['HW-BOOM-001'],'kind'=>'damage','note'=>'Rosca dañada'],'QA'),'técnico');rejects(fn()=>apply_command($s,['type'=>'report_issue','assetIds'=>['HW-BOOM-001'],'kind'=>'damage','note'=>'x','responsibleId'=>'TEC-01'],'QA'),'Describe');$s=apply_command($s,['type'=>'report_issue','assetIds'=>['HW-BOOM-001','ACC-FAN-001'],'kind'=>'damage','note'=>'Rosca dañada','responsibleId'=>'TEC-01'],'QA');check(asset($s,'HW-BOOM-001')['status']==='maintenance'&&asset($s,'HW-BOOM-001')['location']==='Taller');$i=$s['issues'][0];check($i['by']==='Técnico 01'&&$i['status']==='open'&&count($i['assetIds'])===2);$s=apply_command($s,['type'=>'report_issue','assetIds'=>['HW-CLAMP-001'],'kind'=>'missing','note'=>'No está en su rack','responsibleId'=>'TEC-02'],'QA');check(asset($s,'HW-CLAMP-001')['status']==='missing');$s=apply_command($s,['type'=>'issue_close','issueId'=>$i['id'],'note'=>'Reparado'],'QA');check($s['issues'][1]['status']==='closed');rejects(fn()=>apply_command($s,['type'=>'issue_close','issueId'=>$i['id']],'QA'),'cerrado');rejects(fn()=>apply_command($s,['type'=>'crew_photo','crewId'=>'TEC-01','photo'=>'data:image/png;base64,AAAA'],'QA'),'JPEG');$s=apply_command($s,['type'=>'crew_photo','crewId'=>'TEC-01','photo'=>'data:image/jpeg;base64,'.base64_encode("\xFF\xD8\xFFtest")],'QA');check(str_starts_with($s['crew'][0]['photo'],'data:image/jpeg')); });
test('Afiche del evento: opcional, solo JPEG liviano, se cambia y se quita',function(){ $s=seed_state();$jpg='data:image/jpeg;base64,'.base64_encode("\xFF\xD8\xFFafiche");$ids=['HW-BOOM-001'];rejects(fn()=>apply_command($s,event_cmd($ids)+['poster'=>'data:image/png;base64,AAAA'],'QA'),'JPEG');rejects(fn()=>apply_command($s,event_cmd($ids)+['poster'=>'data:image/jpeg;base64,'.str_repeat('A',270000)],'QA'),'JPEG');$s=apply_command($s,event_cmd($ids)+['poster'=>$jpg],'QA');$e=end($s['events']);check($e['poster']===$jpg);$s=apply_command($s,['type'=>'event_poster','eventId'=>$e['id'],'poster'=>''],'QA');check(end($s['events'])['poster']==='');$s2=apply_command(seed_state(),event_cmd(['ACC-FAN-001']),'QA');check(end($s2['events'])['poster']===''); });
test('Código interno editable: conserva el id del QR y evita duplicados',function(){ $s=seed_state();$a=$s['assets'][0];$o=$s['assets'][1];$up=fn($st,$code)=>apply_command($st,['type'=>'asset_update','assetId'=>$a['id'],'name'=>$a['name'],'category'=>$a['category'],'code'=>$code],'QA');$s=$up($s,'nuevo-cod-01');$n=asset($s,$a['id']);check($n['code']==='NUEVO-COD-01'&&$n['id']===$a['id']);rejects(fn()=>$up($s,$o['code']),'otro equipo');rejects(fn()=>$up($s,$s['kits'][0]['id']),'otro equipo');rejects(fn()=>$up($s,'x'),'código de 3');rejects(fn()=>apply_command($s,['type'=>'create_asset','code'=>$a['id'],'name'=>'Copia','category'=>'Accesorios','location'=>'Bodega A'],'QA'),'ya existe');$s=$up($s,$a['id']);check(asset($s,$a['id'])['code']===$a['id']);$s=apply_command($s,['type'=>'asset_update','assetId'=>$a['id'],'name'=>'Solo nombre','category'=>$a['category']],'QA');check(asset($s,$a['id'])['code']===$a['id']); });
test('Técnicos: agregar, eliminar (queda en historial) y reincorporar',function(){ $s=seed_state();$s=apply_command($s,['type'=>'crew_add','name'=>'Ana Rock'],'QA');$t=end($s['crew']);check($t['id']==='TEC-11'&&$t['active']===true);rejects(fn()=>apply_command($s,['type'=>'crew_add','name'=>'ana rock'],'QA'),'Ya hay');$s=apply_command($s,['type'=>'crew_remove','crewId'=>'TEC-11'],'QA');check(end($s['crew'])['active']===false&&count($s['crew'])===11);rejects(fn()=>crew_name($s,'TEC-11'),'técnico');rejects(fn()=>apply_command($s,['type'=>'crew_remove','crewId'=>'TEC-11'],'QA'),'no encontrado');$s=apply_command($s,['type'=>'crew_add','name'=>'Ana Rock'],'QA');check(count($s['crew'])===11&&end($s['crew'])['active']===true);$solo=seed_state();for($n=1;$n<=9;$n++)$solo=apply_command($solo,['type'=>'crew_remove','crewId'=>sprintf('TEC-%02d',$n)],'QA');rejects(fn()=>apply_command($solo,['type'=>'crew_remove','crewId'=>'TEC-10'],'QA'),'al menos'); });
test('Event Timing: datos del evento, escenarios y Run of Show validado',function(){ $s=seed_state();$ev=$s['events'][0]['id'];$d=date('Y-m-d',strtotime('+1 day'));
  $s=apply_command($s,['type'=>'event_update','eventId'=>$ev,'client'=>'Productora QA','address'=>'Calle 1','status'=>'confirmed','stageManagerId'=>'TEC-01','stages'=>[['id'=>'S1','name'=>'Principal'],['id'=>'S2','name'=>'Carpa']],'notes'=>'x'],'QA');check($s['events'][0]['status']==='confirmed'&&count($s['events'][0]['stages'])===2);
  rejects(fn()=>apply_command($s,['type'=>'event_update','eventId'=>$ev,'status'=>'otro'],'QA'),'Estado');
  $acts=[['id'=>'AB2','type'=>'performance','title'=>'Banda 2','stageId'=>'S1','start'=>$d.'T22:00','end'=>$d.'T23:00'],['id'=>'AB1','type'=>'performance','title'=>'Banda 1','stageId'=>'S1','start'=>$d.'T20:30','end'=>$d.'T21:30','responsibleId'=>'TEC-02'],['id'=>'ACO','type'=>'changeover','title'=>'Changeover','stageId'=>'S1','start'=>$d.'T21:30','end'=>$d.'T22:00']];
  $s=apply_command($s,['type'=>'timing_save','eventId'=>$ev,'activities'=>$acts],'QA');$t=$s['events'][0]['timing'];check(count($t)===3&&$t[0]['id']==='AB1');
  rejects(fn()=>apply_command($s,['type'=>'timing_save','eventId'=>$ev,'activities'=>[['id'=>'AX1','type'=>'performance','title'=>'Mal','stageId'=>'S1','start'=>$d.'T22:00','end'=>$d.'T21:00']]],'QA'),'terminar');
  rejects(fn()=>apply_command($s,['type'=>'timing_save','eventId'=>$ev,'activities'=>[['id'=>'AX1','type'=>'nope','title'=>'X','stageId'=>'S1','start'=>$d.'T20:00','end'=>$d.'T21:00']]],'QA'),'Tipo');
  rejects(fn()=>apply_command($s,['type'=>'timing_save','eventId'=>$ev,'activities'=>[['id'=>'AX1','type'=>'custom','title'=>'X','stageId'=>'S9','start'=>$d.'T20:00','end'=>$d.'T21:00']]],'QA'),'Escenario');
  rejects(fn()=>apply_command($s,['type'=>'event_update','eventId'=>$ev,'stages'=>[['id'=>'S2','name'=>'Carpa']]],'QA'),'actividades');
  check(count($s['assets'])===151); });
test('Crear un kit agrupa activos existentes sin duplicar stock',function(){ $s=apply_command(seed_state(),['type'=>'create_kit','name'=>'Kit escenario B','assetIds'=>['HW-BOOM-001','HW-SS-001']],'QA');$k=end($s['kits']);check(count($s['assets'])===151);check(count($s['kits'])===3);check(asset($s,'HW-BOOM-001')['kitId']===$k['id']);check(count($k['expectedIds'])===2); });
$dbFile=sys_get_temp_dir().'/kb-test-'.bin2hex(random_bytes(6)).'.sqlite';
try {
    $store=new SqlStore(['dsn'=>'sqlite:'.$dbFile]);$store->migrate();$store->save(seed_state());
    test('SQL persiste entre conexiones independientes',function()use($store,$dbFile){$s=$store->command(event_cmd(['MAR-1960B-001']),'Operador A',0);$other=new SqlStore(['dsn'=>'sqlite:'.$dbFile]);check($other->read()['revision']===1);check(asset($other->read(),'MAR-1960B-001')['status']==='reserved');});
    test('Una revisión antigua no sobrescribe cambios de otro operador',function()use($store){rejects(fn()=>$store->command(event_cmd(['MAR-1960B-002']),'Operador B',0),'CONFLICT');check(asset($store->read(),'MAR-1960B-002')['status']==='available');});
    test('Una operación inválida revierte la transacción sin alterar inventario',function()use($store){$before=$store->read();rejects(fn()=>$store->command(event_cmd(['MAR-1960B-002','HW-BOOM-008']),'QA',$before['revision']));check($store->read()===$before);});
    test('SQL limita intentos repetidos de acceso',function()use($store){for($i=0;$i<15;$i++)$store->authAttempt('qa');rejects(fn()=>$store->authAttempt('qa'),'Demasiados');});
} finally {if(is_file($dbFile))unlink($dbFile);}
echo "\n$passed tests passed. PHP ".PHP_VERSION."\n";
